-- Arbeitsrecht Berufsbildung > Kündigungsschutz > Besonderer Schutz in der Ausbildung (§ 22 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Genießt ein Fachinformatiker nach der Probezeit einen besonderen Kündigungsschutz?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG schützt durch Kündigungsfristen und wichtige Gründe"}, {"text": "Nein", "correct": false, "because": "Besonderer Schutz gilt nach Probezeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb einen Fachinformatiker nach der Probezeit ohne wichtigen Grund kündigen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt einen wichtigen Grund"}, {"text": "Ja", "correct": false, "because": "Kündigungsschutz greift"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Kündigung eines Fachinformatikers nach der Probezeit schriftlich erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert Schriftform"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker während der Probezeit besonderen Kündigungsschutz beanspruchen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 1 BBiG sieht keinen Schutz in der Probezeit vor"}, {"text": "Ja", "correct": false, "because": "Probezeit ohne besonderen Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb einen Fachinformatiker fristlos kündigen, wenn ein wichtiger Grund vorliegt?', 2, '[{"text": "Ja", "correct": true, "because": "§ 22 Abs. 2 BBiG erlaubt dies bei wichtigem Grund"}, {"text": "Nein", "correct": false, "because": "Fristlose Kündigung ist möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage bietet einem Fachinformatiker besonderen Kündigungsschutz?', 2, '[{"text": "§ 22 BBiG", "correct": true, "because": "Regelt den Kündigungsschutz in der Ausbildung"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Arbeitgeberpflichten"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lange beträgt die Kündigungsfrist für eine ordentliche Kündigung eines Fachinformatikers nach der Probezeit?', 3, '[{"text": "4 Wochen zum Monatsende", "correct": true, "because": "§ 22 Abs. 2 BBiG legt dies fest"}, {"text": "2 Wochen jederzeit", "correct": false, "because": "Nur in der Probezeit"}, {"text": "Sofort ohne Frist", "correct": false, "because": "Fristen sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund rechtfertigt eine außerordentliche Kündigung eines Fachinformatikers nach der Probezeit?', 3, '[{"text": "Schwere Pflichtverletzung", "correct": true, "because": "§ 22 Abs. 2 BBiG sieht dies als wichtigen Grund"}, {"text": "Einmalige Verspätung", "correct": false, "because": "Nicht schwerwiegend genug"}, {"text": "Unzufriedenheit des Betriebs", "correct": false, "because": "Kein wichtiger Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer genießt nach § 22 BBiG besonderen Kündigungsschutz?', 2, '[{"text": "Ein Fachinformatiker nach der Probezeit", "correct": true, "because": "§ 22 Abs. 2 BBiG schützt nach Probezeit"}, {"text": "Ein Fachinformatiker in der Probezeit", "correct": false, "because": "Probezeit ohne Schutz"}, {"text": "Die IHK", "correct": false, "because": "IHK hat keinen Schutzstatus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb tun, wenn er einen Fachinformatiker nach der Probezeit ordentlich kündigen will?', 3, '[{"text": "Schriftlich kündigen mit Frist und Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt dies"}, {"text": "Mündlich kündigen ohne Frist", "correct": false, "because": "Schriftform und Frist sind Pflicht"}, {"text": "Nur die IHK informieren", "correct": false, "because": "Nicht ausreichend"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Regelungen bieten einem Fachinformatiker besonderen Kündigungsschutz nach § 22 BBiG?', 4, '[{"text": "Schriftform bei Kündigung", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}, {"text": "Kündigungsfrist von 4 Wochen nach Probezeit", "correct": true, "because": "§ 22 Abs. 2 BBiG legt dies fest"}, {"text": "Kündigung ohne Grund jederzeit", "correct": false, "because": "Wichtiger Grund erforderlich"}, {"text": "Wichtiger Grund bei außerordentlicher Kündigung", "correct": true, "because": "§ 22 Abs. 2 BBiG schützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen muss eine Kündigung eines Fachinformatikers nach der Probezeit erfüllen?', 3, '[{"text": "Schriftform", "correct": true, "because": "§ 22 Abs. 2 BBiG verlangt dies"}, {"text": "Wichtiger Grund", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}, {"text": "Mündliche Mitteilung", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Frist von 4 Wochen zum Monatsende", "correct": true, "because": "Bei ordentlicher Kündigung vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe können eine außerordentliche Kündigung eines Fachinformatikers rechtfertigen?', 4, '[{"text": "Wiederholtes Schwänzen der Berufsschule", "correct": true, "because": "Schwere Pflichtverletzung"}, {"text": "Verletzung der Verschwiegenheit", "correct": true, "because": "Wichtiger Grund"}, {"text": "Einmalige Unpünktlichkeit", "correct": false, "because": "Nicht ausreichend"}, {"text": "Betriebsstilllegung", "correct": true, "because": "Wichtiger Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Fachinformatiker nach der Probezeit bei einer Kündigung?', 3, '[{"text": "Schriftliche Kündigung", "correct": true, "because": "§ 22 Abs. 2 BBiG schützt dies"}, {"text": "Fristgerechte Kündigung", "correct": true, "because": "§ 22 Abs. 2 BBiG legt Fristen fest"}, {"text": "Sofortige Wiedereinstellung", "correct": false, "because": "Kein automatisches Recht"}, {"text": "Begründung bei außerordentlicher Kündigung", "correct": true, "because": "Wichtiger Grund erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Betrieb nicht tun, wenn er einen Fachinformatiker nach der Probezeit kündigt?', 3, '[{"text": "Ohne wichtigen Grund kündigen", "correct": true, "because": "§ 22 Abs. 2 BBiG verbietet dies"}, {"text": "Mündlich kündigen", "correct": true, "because": "Schriftform ist Pflicht"}, {"text": "Frist von 4 Wochen einhalten", "correct": false, "because": "Das ist zulässig"}, {"text": "Schriftlich mit Grund kündigen", "correct": false, "because": "Das ist erforderlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Fachinformatiker hat nach der Probezeit besonderen Kündigungsschutz. b) In der Probezeit gilt derselbe Schutz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nach Probezeit Schutz, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nach der Probezeit beträgt die Kündigungsfrist 4 Wochen. b) Eine außerordentliche Kündigung erfordert einen wichtigen Grund.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 22 Abs. 2 BBiG bestätigt beides"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Betrieb kann einen Fachinformatiker nach der Probezeit ohne Frist kündigen. b) Die Kündigung muss schriftlich sein.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Schriftform Pflicht, a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der besondere Kündigungsschutz gilt nur nach der Probezeit. b) Eine fristlose Kündigung ist ohne Grund möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz nach Probezeit, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) § 22 BBiG bietet Fachinformatikern Schutz nach der Probezeit. b) Die Kündigungsfrist beträgt in der Probezeit 4 Wochen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz nach Probezeit, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');